t.script:
(function () {
    var el = function (id) { return document.getElementById(id); };
    var combos = JSON.parse(el('aa_cts_form').dataset.combos || '{}');
    var timer = null;

    function rpc(url, spec) {
        return fetch(url, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {spec: spec}})
        }).then(function (r) { return r.json(); }).then(function (r) {
            return r.error ? {error: 'Something went wrong - please call us to order.'} : r.result;
        });
    }

    function spec() {
        return {
            id: el('aa_cts_id').value, wire: el('aa_cts_wire').value,
            length: el('aa_cts_length').value, wind: el('aa_cts_wind').value, qty: el('aa_cts_qty').value
        };
    }

    function fillWires() {
        var sel = el('aa_cts_wire'), cur = sel.value;
        sel.innerHTML = '';
        (combos[el('aa_cts_id').value] || []).forEach(function (w) {
            var o = document.createElement('option');
            o.value = w; o.textContent = '.' + w;
            sel.appendChild(o);
        });
        if (cur) { sel.value = cur; }
        if (!sel.value && sel.options.length) { sel.selectedIndex = 0; }
    }

    function show(d) {
        el('aa_cts_add').disabled = true;
        el('aa_cts_error').textContent = '';
        if (!d || d.error) {
            el('aa_cts_result').classList.add('d-none');
            el('aa_cts_error').textContent = d ? d.error : '';
            return;
        }
        el('aa_cts_springs').textContent = d.springs;
        el('aa_cts_weight').textContent = d.weight + ' lb';
        el('aa_cts_total').textContent = '$' + Number(d.total).toFixed(2);
        el('aa_cts_result').classList.remove('d-none');
        el('aa_cts_add').disabled = false;
    }

    function refresh() {
        if (!el('aa_cts_length').value) { show(null); return; }
        rpc('/custom-torsion-spring/quote', spec()).then(show);
    }

    function later() { el('aa_cts_add').disabled = true; clearTimeout(timer); timer = setTimeout(refresh, 300); }

    el('aa_cts_id').addEventListener('change', function () { fillWires(); later(); });
    ['aa_cts_wire', 'aa_cts_wind'].forEach(function (id) { el(id).addEventListener('change', later); });
    ['aa_cts_length', 'aa_cts_qty'].forEach(function (id) { el(id).addEventListener('input', later); });
    el('aa_cts_add').addEventListener('click', function () {
        el('aa_cts_add').disabled = true;
        rpc('/custom-torsion-spring/add-to-cart', spec()).then(function (d) {
            if (d && !d.error) { window.location.href = '/shop/cart'; }
            else { show(d); }
        });
    });
    fillWires();
})();
